/**
 * Tokenizer module for converting various input types to standardized tokens.
 *
 * This Scala translation demonstrates:
 * - Sealed traits for safe algebraic data types
 * - Type classes for extensible polymorphism
 * - Immutable data structures and case classes
 * - Generic variance with covariance and contravariance
 * - Error handling with Either and Option
 * - Functional programming patterns (map, flatMap, fold)
 *
 * This implementation follows Scala conventions and best practices,
 * leveraging the language's strong type system and functional paradigms.
 */

import scala.collection.immutable._
import scala.reflect.ClassTag
import scala.util.control.Exception._
import java.time.{LocalDate, LocalDateTime}
import scala.math.BigDecimal
import java.nio.charset.Charset
import scala.annotation.implicitNotFound
import scala.language.implicitConversions

// ============================================================================
// Token Type ADT
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value = "string" }
  case object NUMERIC extends TokenType { val value = "numeric" }
  case object TEMPORAL extends TokenType { val value = "temporal" }
  case object STRUCTURED extends TokenType { val value = "structured" }
  case object BINARY extends TokenType { val value = "binary" }
  case object NULL extends TokenType { val value = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
 * Immutable token representation.
 * Case class provides structural equality, hashCode, and copy for immutability.
 */
final case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {

  /**
   * Return new token with additional metadata.
   * Demonstrates immutability and composition.
   */
  def withMetadata(entries: (String, Any)*): Token =
    copy(metadata = metadata ++ entries.toMap)

  /**
   * Convenience method to add a single metadata entry.
   */
  def withMetadata(key: String, value: Any): Token =
    copy(metadata = metadata + (key -> value))
}

/**
 * Mutable batch of tokens for efficient bulk processing.
 * Contrast with immutable Token - demonstrates when mutability is appropriate.
 */
final class MutableTokenBatch private (private val _tokens: scala.collection.mutable.ListBuffer[Token],
                                        private var _processed: Boolean = false) {

  /**
   * Add a token to the batch.
   * Throws exception if batch has been marked as processed.
   */
  def add(token: Token): this.type = {
    if (_processed) throw new IllegalStateException("Batch already processed")
    _tokens += token
    this
  }

  /**
   * Mark the batch as processed.
   */
  def markProcessed(): Unit = {
    _processed = true
  }

  /**
   * Get all tokens as immutable list.
   */
  def tokens: List[Token] = _tokens.toList

  /**
   * Check if batch has been processed.
   */
  def isProcessed: Boolean = _processed
}

object MutableTokenBatch {
  def apply(): MutableTokenBatch = new MutableTokenBatch(scala.collection.mutable.ListBuffer.empty)
  def apply(initialTokens: Token*): MutableTokenBatch =
    new MutableTokenBatch(scala.collection.mutable.ListBuffer(initialTokens: _*))
}

// ============================================================================
// Type Classes for Tokenization (replaces Protocol)
// ============================================================================

/**
 * Type class for objects that can be converted to tokens.
 * More idiomatic than Python's Protocol for Scala.
 */
@implicitNotFound("${A} cannot be converted to a token")
trait Tokenizable[A] {
  def toToken(value: A): String
}

object Tokenizable {
  implicit val stringTokenizable: Tokenizable[String] = (v: String) => v
  implicit val intTokenizable: Tokenizable[Int] = (v: Int) => v.toString
}

/**
 * Type class for objects with length.
 */
@implicitNotFound("${A} has no length")
trait HasLength[A] {
  def length(value: A): Int
}

object HasLength {
  implicit val stringHasLength: HasLength[String] = (v: String) => v.length
  implicit val listHasLength[A]: HasLength[List[A]] = (v: List[A]) => v.length
  implicit def seqHasLength[A]: HasLength[Seq[A]] = (v: Seq[A]) => v.length
}

/**
 * Type class for token processors (contravariant in spirit).
 */
trait TokenProcessor[-A] {
  def process(item: A): Unit
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
 * Covariant container - enables return of subtypes.
 * Uses List[+T_co] which is covariant in T_co.
 */
final case class TokenContainer[+T](items: List[T]) {

  /**
   * Get all items.
   */
  def getAll: List[T] = items

  /**
   * Map over items using a function.
   */
  def mapTokens[S](func: T => String): List[String] =
    items.map(func)

  /**
   * Fold operation.
   */
  def fold[S](initial: S)(f: (S, T) => S): S =
    items.foldLeft(initial)(f)

  /**
   * Size of container.
   */
  def size: Int = items.length
}

/**
 * Contravariant sink for accepting supertypes.
 */
final class TokenSink[-T] {
  private val _received: scala.collection.mutable.ListBuffer[Any] =
    scala.collection.mutable.ListBuffer.empty

  /**
   * Receive an item.
   */
  def receive(item: T): Unit = {
    _received += item
  }

  /**
   * Drain all received items and clear.
   */
  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }

  /**
   * Size of received items.
   */
  def size: Int = _received.size
}

/**
 * Invariant handler requiring exact type matching.
 * Uses mutable reference for stateful transformation.
 */
final class BivariantHandler[T](initial: T) {
  private var _value: T = initial

  /**
   * Get current value.
   */
  def get(): T = _value

  /**
   * Set value.
   */
  def set(value: T): Unit = {
    _value = value
  }

  /**
   * Transform value.
   */
  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Base Tokenizer and Implementations
// ============================================================================

/**
 * Abstract base tokenizer with generic input type.
 * Uses monadic and applicative patterns with Lists/Iterators.
 */
abstract class BaseTokenizer[T] {

  /**
   * Convert value to token.
   */
  def tokenize(value: T): Token

  /**
   * Lazy tokenization of multiple values.
   * Returns an Iterator for memory efficiency with large datasets.
   */
  def tokenizeBatch(values: IterableOnce[T]): Iterator[Token] =
    values.iterator.map(tokenize)

  /**
   * Batch tokenization returning a List.
   */
  def tokenizeBatchList(values: IterableOnce[T]): List[Token] =
    values.iterator.map(tokenize).toList

  /**
   * Map function for composing tokenizers.
   */
  def map[S](f: Token => S): BaseTokenizer[T] = new BaseTokenizer[T] {
    override def tokenize(value: T): Token = BaseTokenizer.this.tokenize(value)
  }
}

/**
 * Tokenizer for string and bytes types.
 */
class StringTokenizer(
    encoding: String = "UTF-8",
    normalizer: String => String = identity
) extends BaseTokenizer[String] {

  /**
   * Tokenize string input.
   */
  override def tokenize(value: String): Token = {
    val normalized = normalizer(value)
    Token(normalized, TokenType.STRING)
  }

  /**
   * Tokenize bytes input by decoding first.
   */
  def tokenizeBytes(value: Array[Byte]): Token = {
    val decoded = new String(value, Charset.forName(encoding))
    tokenize(decoded)
  }
}

/**
 * Tokenizer for numeric types with precision handling.
 * Uses pattern matching instead of type checking for more idiomatic Scala.
 */
class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Number] {

  /**
   * Tokenize numeric value with appropriate formatting.
   */
  override def tokenize(value: Number): Token = {
    val (strValue, originalType) = value match {
      case bd: BigDecimal => (f"$bd%.${precision}f", "BigDecimal")
      case d: Double      => (f"$d%.${precision}f", "Double")
      case f: Float       => (f"$f%.${precision}f", "Float")
      case bd: java.math.BigDecimal =>
        (f"${bd.doubleValue()}%.${precision}f", "BigDecimal")
      case i: Integer     => (i.toString, "Integer")
      case l: Long        => (l.toString, "Long")
      case _              => (value.toString, value.getClass.getSimpleName)
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> originalType))
  }

  /**
   * Convenience methods for specific numeric types.
   */
  def tokenizeInt(value: Int): Token = tokenize(Integer.valueOf(value))
  def tokenizeDouble(value: Double): Token = tokenize(Double.box(value))
  def tokenizeDecimal(value: BigDecimal): Token = tokenize(value.underlying)
}

/**
 * Tokenizer for date/time types.
 */
class TemporalTokenizer(
    formatString: Option[String] = None
) extends BaseTokenizer[java.time.temporal.Temporal] {

  private val IsoFormat = "yyyy-MM-dd'T'HH:mm:ss"
  private val DateFormat = "yyyy-MM-dd"

  /**
   * Tokenize temporal value with appropriate format.
   */
  override def tokenize(value: java.time.temporal.Temporal): Token = {
    val formatter = formatString.getOrElse {
      value match {
        case _: LocalDateTime => IsoFormat
        case _: LocalDate     => DateFormat
        case _                => DateFormat
      }
    }

    val formattedValue = value match {
      case ldt: LocalDateTime =>
        ldt.format(java.time.format.DateTimeFormatter.ofPattern(formatter))
      case ld: LocalDate =>
        ld.format(java.time.format.DateTimeFormatter.ofPattern(formatter))
      case other =>
        other.toString
    }

    Token(formattedValue, TokenType.TEMPORAL)
  }
}

// ============================================================================
// Universal Tokenizer with Type Class Instance Resolution
// ============================================================================

/**
 * Tokenizer that handles multiple types through pattern matching and type classes.
 * More type-safe than Python's isinstance checks through Scala's type system.
 */
class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  /**
   * Dispatch to appropriate tokenizer based on actual runtime type.
   * Returns Either to handle errors naturally in Scala.
   */
  def tokenize(value: Any): Either[String, Token] = {
    value match {
      case null =>
        Right(Token("NULL", TokenType.NULL))

      case tv: Tokenizable[_] =>
        Right(Token(tv.asInstanceOf[Tokenizable[Any]].toToken(value), TokenType.STRUCTURED))

      case s: String =>
        Right(stringTokenizer.tokenize(s))

      case ba: Array[Byte] =>
        Right(stringTokenizer.tokenizeBytes(ba))

      case n: Number =>
        Right(numericTokenizer.tokenize(n))

      case ld: LocalDate =>
        Right(temporalTokenizer.tokenize(ld))

      case ldt: LocalDateTime =>
        Right(temporalTokenizer.tokenize(ldt))

      case dt: java.util.Date =>
        val instant = dt.toInstant
        val zoned = instant.atZone(java.time.ZoneId.systemDefault())
        Right(temporalTokenizer.tokenize(zoned.toLocalDate))

      case other =>
        // Fallback: try string conversion
        Right(Token(other.toString, TokenType.STRING, Map("fallback" -> true)))
    }
  }

  /**
   * Safe tokenize with Option for potentially null values.
   */
  def tokenizeOption(value: Option[Any]): Token = {
    value match {
      case Some(v) => tokenize(v).getOrElse(Token(v.toString, TokenType.STRING))
      case None    => Token("NULL", TokenType.NULL)
    }
  }
}

// ============================================================================
// Token Registry with Complex Nested Generics
// ============================================================================

/**
 * Registry with complex nested generic types.
 * Demonstrates proper handling of mutable collections with generics in Scala.
 */
final class TokenRegistry[T] {
  private val _registry: scala.collection.mutable.Map[String, TokenContainer[T]] =
    scala.collection.mutable.Map.empty
  private val _handlers: scala.collection.mutable.ListBuffer[T => Option[Token]] =
    scala.collection.mutable.ListBuffer.empty

  /**
   * Register a container under a key.
   */
  def register(key: String, container: TokenContainer[T]): Unit = {
    _registry(key) = container
  }

  /**
   * Add a handler function.
   */
  def addHandler(handler: T => Option[Token]): Unit = {
    _handlers += handler
  }

  /**
   * Process all items in a container through all handlers.
   */
  def process(key: String): List[Option[Token]] = {
    _registry.get(key) match {
      case Some(container) =>
        container.getAll.map { item =>
          _handlers.collectFirst { case handler if handler(item).isDefined =>
            handler(item).get
          }
        }
      case None => List.empty
    }
  }

  /**
   * Get all registered keys.
   */
  def keys: Set[String] = _registry.keySet.toSet
}

// ============================================================================
// Functor and Monad Type Classes for Tokens
// ============================================================================

/**
 * Functor for tokens - proper type class implementation.
 */
trait TokenFunctor[T] {
  def map[S](func: T => S): TokenFunctor[S]
}

/**
 * Implementation of TokenFunctor for values.
 */
final case class TokenValue[T](value: T) extends TokenFunctor[T] {
  override def map[S](func: T => S): TokenFunctor[S] =
    TokenValue(func(value))

  def flatMap[S](func: T => TokenValue[S]): TokenValue[S] =
    func(value)

  def getOrElse(default: T): T =
    if (value != null) value else default
}

/**
 * Monad for tokens with extended operations.
 */
trait TokenMonad[T] extends TokenFunctor[T] {
  def flatMap[S](func: T => TokenMonad[S]): TokenMonad[S]
  def pure[S](value: S): TokenMonad[S]
  def ap[S](funcWrapped: TokenMonad[T => S]): TokenMonad[S]
}

/**
 * Implementation of TokenMonad.
 */
final case class TokenMonadImpl[T](value: T) extends TokenMonad[T] {
  override def map[S](func: T => S): TokenFunctor[S] =
    TokenMonadImpl(func(value))

  override def flatMap[S](func: T => TokenMonad[S]): TokenMonad[S] =
    func(value)

  override def pure[S](v: S): TokenMonad[S] =
    TokenMonadImpl(v)

  override def ap[S](funcWrapped: TokenMonad[T => S]): TokenMonad[S] =
    funcWrapped match {
      case TokenMonadImpl(f: (T => S)) => TokenMonadImpl(f(value))
      case _                           => TokenMonadImpl(null)
    }
}

// ============================================================================
// JSON/Structured Data Tokenization
// ============================================================================

/**
 * Recursive type for JSON-like structures using case classes.
 */
sealed trait JsonValue
object JsonValue {
  case class JsonString(value: String) extends JsonValue
  case class JsonNumber(value: Double) extends JsonValue
  case class JsonBoolean(value: Boolean) extends JsonValue
  case object JsonNull extends JsonValue
  case class JsonArray(value: Vector[JsonValue]) extends JsonValue
  case class JsonObject(value: Map[String, JsonValue]) extends JsonValue

  def fromAny(any: Any): JsonValue = any match {
    case null              => JsonNull
    case s: String         => JsonString(s)
    case d: Double         => JsonNumber(d)
    case i: Int            => JsonNumber(i.toDouble)
    case b: Boolean        => JsonBoolean(b)
    case arr: Seq[_]       => JsonArray(arr.map(fromAny).toVector)
    case map: Map[_, _]    => JsonObject(map.asInstanceOf[Map[String, Any]].mapValues(fromAny))
    case _                 => JsonString(any.toString)
  }
}

/**
 * Tokenizer for JSON structures with recursive type handling.
 */
class JsonTokenizer(pretty: Boolean = false) {

  /**
   * Tokenize a JSON value.
   */
  def tokenize(value: JsonValue): Token = {
    val jsonStr = renderJson(value)
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  /**
   * Extract and tokenize a value at a JSON path.
   */
  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split('.')
    val extracted = parts.foldLeft[Option[JsonValue]](Some(value)) {
      case (None, _) => None
      case (Some(JsonObject(map)), part) =>
        map.get(part)
      case (Some(JsonArray(arr)), part) if part.forall(_.isDigit) =>
        val idx = part.toInt
        if (0 <= idx && idx < arr.length) Some(arr(idx)) else None
      case _ => None
    }

    extracted.map(tokenize)
  }

  /**
   * Render JSON to string.
   */
  private def renderJson(value: JsonValue): String = {
    import JsonValue._
    value match {
      case JsonNull           => "null"
      case JsonBoolean(b)     => b.toString
      case JsonString(s)      => s""""$s""""
      case JsonNumber(n)      => n.toString
      case JsonArray(arr)     =>
        val items = arr.map(renderJson).mkString(",")
        s"[$items]"
      case JsonObject(map)    =>
        val items = map.map { case (k, v) => s""""$k":${renderJson(v)}""" }.mkString(",")
        s"{$items}"
    }
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 * Demonstrates a practical, fundamental tokenization operation.
 */
class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = Set(".,!?;:'\"()[]{}")

  /**
   * Process a single word into a token string.
   */
  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.filterNot(punctuation.contains)
    }

    if (lowercase) {
      processed = processed.toLowerCase()
    }

    if (processed.length < minLength) {
      None
    } else if (maxLength.exists(processed.length > _)) {
      Some(processed.take(maxLength.get))
    } else if (processed.nonEmpty) {
      Some(processed)
    } else {
      None
    }
  }

  /**
   * Split text by whitespace and return list of tokens.
   */
  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").toList
    words.zipWithIndex.flatMap {
      case (word, idx) =>
        processToken(word).map { processed =>
          Token(
            processed,
            TokenType.STRING,
            Map("position" -> idx, "original" -> word)
          )
        }
    }
  }

  /**
   * Split text by whitespace and return list of token strings.
   */
  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  /**
   * Tokenize text and return tokens with character positions.
   */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+")
    var currentPos = 0
    val result = scala.collection.mutable.ListBuffer.empty[(String, Int, Int)]

    for (word <- words) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  /**
   * Return the number of tokens in the text.
   */
  def countTokens(text: String): Int =
    tokenize(text).length
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Fluent builder for creating tokenizers.
 * Demonstrates builder pattern with method chaining for composing complex tokenizers.
 */
class TokenizerBuilder[T] {
  private val normalizers: scala.collection.mutable.ListBuffer[String => String] =
    scala.collection.mutable.ListBuffer.empty
  private val validators: scala.collection.mutable.ListBuffer[T => Boolean] =
    scala.collection.mutable.ListBuffer.empty
  private val metadataMap: scala.collection.mutable.Map[String, Any] =
    scala.collection.mutable.Map.empty

  /**
   * Add a normalizer function to the builder.
   */
  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  /**
   * Add a validator function to the builder.
   */
  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  /**
   * Add metadata entries to the builder.
   */
  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] = {
    metadataMap ++= entries.toMap
    this
  }

  /**
   * Build the final tokenizer function.
   */
  def build(): T => Either[String, Token] = {
    val normalizersCopy = normalizers.toList
    val validatorsCopy = validators.toList
    val metadataCopy = metadataMap.toMap

    { value: T =>
      // Validate
      validatorsCopy.find(!_(value)) match {
        case Some(_) => Left(s"Validation failed for $value")
        case None    =>
          // Convert to string and normalize
          val strValue = value.toString
          val normalized = normalizersCopy.foldLeft(strValue) { (s, norm) =>
            norm(s)
          }

          Right(Token(normalized, TokenType.STRING, metadataCopy))
      }
    }
  }

  /**
   * Build a simpler tokenizer that may throw on validation failure.
   */
  def buildUnsafe(): T => Token = { value: T =>
    build()(value) match {
      case Left(error)  => throw new IllegalArgumentException(error)
      case Right(token) => token
    }
  }
}

// ============================================================================
// Convenience Functions and Entry Points
// ============================================================================

object Tokenizer {

  /**
   * Create a whitespace tokenizer with sensible defaults.
   */
  def whitespace(
      lowercase: Boolean = false,
      minLength: Int = 0,
      maxLength: Option[Int] = None
  ): WhitespaceTokenizer =
    new WhitespaceTokenizer(lowercase, minLength, maxLength)

  /**
   * Create a string tokenizer.
   */
  def string(normalizer: String => String = identity): StringTokenizer =
    new StringTokenizer(normalizer = normalizer)

  /**
   * Create a numeric tokenizer.
   */
  def numeric(precision: Int = 6): NumericTokenizer =
    new NumericTokenizer(precision)

  /**
   * Create a temporal tokenizer.
   */
  def temporal(format: Option[String] = None): TemporalTokenizer =
    new TemporalTokenizer(format)

  /**
   * Create a universal tokenizer.
   */
  def universal(): UniversalTokenizer =
    new UniversalTokenizer()

  /**
   * Create a builder for custom tokenizers.
   */
  def builder[T](): TokenizerBuilder[T] =
    new TokenizerBuilder[T]()

  /**
   * Tokenize a single value using UniversalTokenizer.
   */
  def tokenize(value: Any): Either[String, Token] =
    universal().tokenize(value)

  /**
   * Tokenize multiple values, returning a list.
   */
  def tokenizeBatch(values: IterableOnce[Any]): List[Token] =
    values.iterator.map(v => universal().tokenize(v).getOrElse(
      Token(v.toString, TokenType.STRING)
    )).toList

  /**
   * Convert value to token string using Tokenizable type class.
   */
  def toToken[A](value: A)(implicit tokenizable: Tokenizable[A]): String =
    tokenizable.toToken(value)
}

